- ****************************************************************************/
-
-int rk3576_config_gpio(gpio_pinset_t pinset)
-{
-  unsigned int port;
-  unsigned int pin;
-  unsigned int mode;
-  enum rk3576_gpio_drive_e drive;
-  int ret;
-  irqstate_t flags;
