-            }
-          else if ((pinset & GPIO_PUPD_MASK) == GPIO_PULLDOWN)
-            {
-              rk3576_pull_set(RK3576_IOC_ADDR, port, pin, RK3576_PULL_DOWN);
-            }
-          else
-            {
