void rk3576_gpio_set_af(FAR struct gpio_dev_s *handle, unsigned int af)
{
  FAR struct rk3576_gpio_dev_s *dev = (FAR struct rk3576_gpio_dev_s *)handle;
  irqstate_t flags;

